<script setup lang="ts">
import CasePicker from '@/shared/ui/CasePicker.vue'
import RecordList from '@/shared/ui/RecordList.vue'
import {label} from '@/shared/ui/presentation'
import {onMounted,ref} from 'vue'
import {httpClient} from '@/shared/http/client'
interface Batch {id:string;fileName:string;totalRows:number}
interface Row {rowNumber:number;status:string;version:number;values:Record<string,string>;case_id:string|null;error_code:string|null}
const emit=defineEmits<{changed:[]}>(),file=ref<File>(),batches=ref<Batch[]>([]),batchTotal=ref(0),batchPage=ref(1),selected=ref<Batch>(),rows=ref<Row[]>([]),page=ref(1),caseId=ref(''),reason=ref(''),busy=ref(false),message=ref(''),resolutions=ref(''),resolutionPage=ref(1),resolutionTotal=ref(0)
async function run(action:()=>Promise<void>){busy.value=true;message.value='';try{await action()}catch(error){message.value=error instanceof Error?error.message:'导入失败'}finally{busy.value=false}}
async function loadBatches(){const response=(await httpClient.get<{data:{records:Batch[];total:number}}>('/funds/imports',{params:{page:batchPage.value,size:20}})).data.data;batches.value=response.records;batchTotal.value=response.total}
async function load(){if(selected.value){rows.value=(await httpClient.get<{data:{records:Row[]}}>(`/funds/imports/${selected.value.id}/rows`,{params:{page:page.value,size:20}})).data.data.records;const history=(await httpClient.get<{data:{records:unknown[];total:number}}>(`/funds/imports/${selected.value.id}/resolutions`,{params:{page:resolutionPage.value,size:20}})).data.data;resolutions.value=JSON.stringify(history.records,null,2);resolutionTotal.value=history.total}}
async function select(row:Batch){selected.value=row;page.value=1;resolutionPage.value=1;await load()}
async function preview(){if(!file.value)throw new Error('请选择文件');const form=new FormData();form.append('file',file.value);selected.value=(await httpClient.post<{data:Batch}>('/funds/imports',form,{timeout:120_000})).data.data;page.value=1;await loadBatches();await load();message.value='仅预览，尚未记账'}
async function confirm(){if(!selected.value)return;await httpClient.post(`/funds/imports/${selected.value.id}/confirm`,{},{timeout:120_000});await load();emit('changed');message.value='逐行处理完成，请查看行级结果；冲突行仍待人工'}
async function resolve(row:Row){if(!caseId.value||!reason.value.trim())throw Error('请选择核对后的案件并填写更正原因');if(!selected.value)return;await httpClient.post(`/funds/imports/${selected.value.id}/rows/${row.rowNumber}/resolve`,{expectedVersion:row.version,caseId:caseId.value,reason:reason.value});await load()}
async function source(){if(!selected.value)return;const response=await httpClient.get(`/funds/imports/${selected.value.id}/source`,{responseType:'blob'});const url=URL.createObjectURL(response.data);const a=document.createElement('a');a.href=url;a.download=selected.value.fileName;a.click();URL.revokeObjectURL(url)}
function choose(event:Event){file.value=(event.target as HTMLInputElement).files?.[0]}
onMounted(()=>run(loadBatches))
</script>
<template><section><h3>资金导入预览与人工匹配</h3><p>UTF-8 CSV或单工作表XLSX，10 MiB/2000行；金额用文本，时间含时区，禁止公式。</p><pre>transactionNo,direction,claimNo,businessNo,amount,occurredAt,note</pre><input type="file" accept=".csv,.xlsx" @change="choose"/><button :disabled="busy" @click="run(preview)">上传并预览</button><p role="status">{{ message }}</p><button :disabled="busy" @click="run(loadBatches)">刷新本人批次</button><ul><li v-for="batch in batches" :key="batch.id"><button :disabled="busy" @click="run(()=>select(batch))">{{ batch.fileName }} · {{ batch.id }}</button></li></ul><button :disabled="busy||batchPage<=1" @click="batchPage--;run(loadBatches)">批次上一页</button><button :disabled="busy||batchPage*20>=batchTotal" @click="batchPage++;run(loadBatches)">批次下一页</button><div v-if="selected"><p>当前 {{ selected.id }}，{{ selected.totalRows }} 行</p><button :disabled="busy" @click="run(confirm)">确认有效行 / 重试失败行</button><button :disabled="busy" @click="run(source)">受控下载原文件</button><CasePicker v-model="caseId"/><label>核对/更正原因<textarea v-model="reason" maxlength="2000"/></label><article v-for="row in rows" :key="row.rowNumber"><p>第 {{ row.rowNumber }} 行：{{ label(row.status) }} {{ row.error_code?'（'+label(row.error_code)+'）':'' }}</p><RecordList :value="row.values"/><p>匹配案件 {{ row.case_id??'待人工' }}</p><button v-if="['NEEDS_REVIEW','READY','FAILED'].includes(row.status)" :disabled="busy" @click="run(()=>resolve(row))">使用上述案件及原因人工匹配</button></article><button :disabled="busy||page<=1" @click="page--;run(load)">行上一页</button><button :disabled="busy||page*20>=selected.totalRows" @click="page++;run(load)">行下一页</button><h4>人工匹配历史</h4><RecordList :value="resolutions"/><button :disabled="busy||resolutionPage<=1" @click="resolutionPage--;run(load)">历史上一页</button><button :disabled="busy||resolutionPage*20>=resolutionTotal" @click="resolutionPage++;run(load)">历史下一页</button></div></section></template>
<style scoped>section{margin-top:20px}pre{white-space:pre-wrap;overflow-wrap:anywhere}label{display:block;margin:8px 0}input,textarea{max-width:100%;box-sizing:border-box}button{margin:6px}</style>
